def rrf(rankings, k=60):
    scores = {}
    appeared = {}                                  # when each id was first seen, for breaking ties
    for ranking in rankings:
        seen_here = set()
        for position, item in enumerate(ranking, start=1):
            if item in seen_here:
                continue
            seen_here.add(item)
            scores[item] = scores.get(item, 0.0) + 1 / (k + position)
            appeared.setdefault(item, len(appeared))
    return sorted(scores.items(), key=lambda pair: (-pair[1], appeared[pair[0]]))
